// Normalize + whitelist a landing event; compute all derived updates.
//
// SECURITY: lead_id comes from the VERIFIED JWT, never from the request body.
// An unauthenticated body-supplied lead_id would let anyone POST
// video_90/video5_unlocked for any lead (ids are sequential: BS-00001...),
// defeating the "Video-5 lock cannot be bypassed" requirement and poisoning
// every intent score in the funnel.
const v = $('Verify JWT').first().json || {};
const claims = v.payload && typeof v.payload === 'object' ? v.payload : v;
const leadId = claims.lead_id;
if (v.error || !leadId) return []; // fail closed, drop silently

let b = $('Webhook').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
if (!b || !b.event) return [];

const VALID = new Set(['page_opened','video_started','video_25','video_50','video_75',
  'video_90','video_completed','video5_unlocked','terms_viewed','cta_clicked',
  'question_clicked','page_resumed','heartbeat','expiry_page_shown','renew_requested']);
if (!VALID.has(b.event)) return [];

const SCORE = { page_opened:2, video_75:5, video_completed:4, cta_clicked:3 };

// When the scheduler should next look at this lead (Sequences C/D/E timing).
const NEXT_H = { page_opened:3, page_resumed:3, video_started:3, video_25:3,
                 video_50:3, video_75:3, video_90:3, video_completed:0.25,
                 cta_clicked:2, question_clicked:6 };
const SEQ  = { page_opened:'C', page_resumed:'C', video_completed:'D', cta_clicked:'E' };
const CAPI = { page_opened:'page_opened', video_90:'video_watched' };

const num = (x) => (x == null ? null : (Number(x) || 0));
const str = (x, max) => (x == null || x === '' ? null : String(x).slice(0, max || 64));

const watched = Number(b.watched_seconds || b.position_seconds || 0) || 0;
const video   = Number(b.video || 0);

const payload = {
  lead_id:          String(leadId).slice(0, 20),
  event:            b.event,
  video:            video > 0 ? video : null,
  watched_seconds:  num(b.watched_seconds),
  position_seconds: num(b.position_seconds),
  route:            str(claims.route, 20),   // from the JWT, not the body
  client_ts:        str(b.ts, 40),
  session_id:       str(b.session_id, 24),
  score:            SCORE[b.event] || 0,
  resume:           b.event.startsWith('video') ? watched : 0,
  next_action_at:   NEXT_H[b.event] != null
                      ? new Date(Date.now() + NEXT_H[b.event] * 3600 * 1000).toISOString()
                      : null,
  capi_stage:       CAPI[b.event] || null,
  seq:              SEQ[b.event]  || null
};

// ONE base64 parameter, not thirteen. The Postgres node splits its Query
// Parameters on commas AND DROPS EMPTY VALUES, so any multi-parameter form
// silently misaligns the moment one value is empty - which is most events.
// Base64 contains no commas, so nothing can be split, and JSON null survives
// the round trip as a real SQL NULL.
return [{ json: { p: Buffer.from(JSON.stringify(payload)).toString('base64') } }];
